 "content": "def transform(grid):
    """Connect color-1 markers only when they occupy opposite grid edges."""
    out = [row[:] for row in grid]
    h = len(out)
    w = len(out[0]) if h else 0
    top = {c for c in range(w) if out[0][c] == 1} if h else set()
    bottom = {c for c in range(w) if out[h - 1][c] == 1} if h else set()
    for c in top & bottom:
        for r in range(h):
            out[r][c] = 1
    left = {r for r in range(h) if out[r][0] == 1} if w else set()
    right = {r for r in range(h) if out[r][w - 1] == 1} if w else set()
    for r in left & right:
        for c in range(w):
            out[r][c] = 1
    return out
